using System;
using System.Threading.Tasks;

namespace Samples;

public static class Demo
{
    private static async Task<int> TransformAsync(int value)
    {
        await Task.Yield();
        return value * 2 + 3;
    }

    public static async Task<int> ComputeAsync_explicit(int baseValue)
    {
        var left = TransformAsync(baseValue + 6);
        var right = TransformAsync(baseValue - 4);
        var results = await Task.WhenAll(left, right);
        return results[0] + results[1];
    }

    public static async Task Main()
    {
        var result = await ComputeAsync_explicit(3);
        Console.WriteLine("result=" + result);
    }
}

// generic-max | select-maximum / generic-constraint | large / p1
// Defensive variant with descriptive identifiers.

using System;
using System.Collections.Generic;
using System.Linq;

namespace Samples;

public static class Demo
{
    public static T Max_safe<T>(IReadOnlyList<T> values) where T : IComparable<T>
    {
        if (values.Count == 0) throw new ArgumentException("empty list");
        var best = values[0];
        for (var i = 1; i < values.Count; i++)
        {
            if (values[i].CompareTo(best) > 0) best = values[i];
        }
        return best;
    }

    public static void Main()
    {
        Console.WriteLine("int=" + Max_safe(new[] { 1000, 1006, 1012, 1018, 1024, 1030, 1036, 1042, 1048, 1054, 1060, 1066 }));
        Console.WriteLine("str=" + Max_safe(new[] { "alpha", "code", "review" }));
        Console.WriteLine("double=" + Max_safe(new[] { 1000.5, 1006.25 }));
        Console.WriteLine("count=" + new[] { 1, 2, 3 }.Count());
    }
}

