// level-enum | classify / switch-expression | duplicates / p3
// Compact variant.

using System;

namespace Samples;

public static class Demo
{
    public enum Level
    {
        Low = 0,
        Medium = 1,
        High = 2,
        Critical = 3
    }

    public static Level Classify_v2(int score)
    {
        if (score < 0 || score > 100) throw new ArgumentOutOfRangeException(nameof(score));
        return score switch
        {
            < 40 => Level.Low,
            < 70 => Level.Medium,
            < 90 => Level.High,
            _ => Level.Critical
        };
    }

    public static void Main()
    {
        var score = 10;
        var level = Classify_v2(score);
        Console.WriteLine("score=" + score + " level=" + level);
        foreach (var candidate in Enum.GetValues<Level>())
        {
            Console.WriteLine(candidate + "=" + (int)candidate);
        }
    }
}

// word-frequency | count-occurrences / dictionary | duplicates / p3
// Defensive variant with descriptive identifiers.

using System;
using System.Collections.Generic;
using System.Linq;

namespace Samples;

public static class Demo
{
    public static Dictionary<string, int> CountWords_safe(string text)
    {
        var counts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        var cleaned = new string(text.Select(ch => char.IsLetterOrDigit(ch) ? ch : ' ').ToArray());
        foreach (var word in cleaned.Split(' ', StringSplitOptions.RemoveEmptyEntries))
        {
            counts.TryGetValue(word, out var current);
            counts[word] = current + 1;
        }
        return counts;
    }

    public static void Main()
    {
        const string text = "gamma gamma code review gamma gamma";
        var top = CountWords_safe(text)
            .OrderByDescending(pair => pair.Value)
            .ThenBy(pair => pair.Key)
            .Take(5);

        foreach (var pair in top)
        {
            Console.WriteLine(pair.Key + ":" + pair.Value);
        }
    }
}

// binary-search | search / binary-search | large / p4
// Explicit naming and direct control flow.

using System;

namespace Samples;

public static class Demo
{
    public static int BinarySearch_explicit(int[] values, int target)
    {
        if (values is null) throw new ArgumentNullException(nameof(values));
        var low = 0;
        var high = values.Length - 1;
        while (low <= high)
        {
            var middle = low + (high - low) / 2;
            if (values[middle] == target) return middle;
            if (values[middle] < target) low = middle + 1;
            else high = middle - 1;
        }
        return -1;
    }

    public static void Main()
    {
        var values = new[] { 1000, 1009, 1018, 1027, 1036, 1045, 1054, 1063, 1072, 1081, 1090, 1099 };
        Array.Sort(values);
        Console.WriteLine("index=" + BinarySearch_explicit(values, 1054));
        Console.WriteLine(string.Join(",", values));
    }
}

