namespace Samples;

public static class Demo
{
    public static T Max_doc<T>(IReadOnlyList<T> values) where T : IComparable<T>
    {
        if (values.Count == 0) throw new ArgumentException("empty list");
        var best = values[0];
        for (var i = 1; i < values.Count; i++)
        {
            if (values[i].CompareTo(best) > 0) best = values[i];
        }
        return best;
    }

    public static void Main()
    {
        Console.WriteLine("int=" + Max_doc(new[] { 25 }));
        Console.WriteLine("str=" + Max_doc(new[] { "delta", "code", "review" }));
