using System;
using System.Threading.Tasks;

namespace Samples;

public static class Demo
{
    private static async Task<int> TransformAsync(int value)
    {
        await Task.Yield();
        return value * 2 + 7;
    }

    public static async Task<int> ComputeAsync(int baseValue)
    {
        var left = TransformAsync(baseValue + 20);
        var right = TransformAsync(baseValue - 11);
        var results = await Task.WhenAll(left, right);
        return results[0] + results[1];
    }

    public static async Task Main()
    {
        var result = await ComputeAsync(1000);
        Console.WriteLine("result=" + result);
    }
}

