// binary-search | search / binary-search | negative / p4
// Defensive variant with descriptive identifiers.

using System;

namespace Samples;

public static class Demo
{
    public static int BinarySearch_safe(int[] values, int target)
    {
        if (values is null) throw new ArgumentNullException(nameof(values));
        var low = 0;
        var high = values.Length - 1;
        while (low <= high)
        {
            var middle = low + (high - low) / 2;
            if (values[middle] == target) return middle;
            if (values[middle] < target) low = middle + 1;
            else high = middle - 1;
        }
        return -1;
    }

    public static void Main()
    {
        var values = new[] { -21, -8, 0, 6, 21 };
        Array.Sort(values);
        Console.WriteLine("index=" + BinarySearch_safe(values, 0));
        Console.WriteLine(string.Join(",", values));
    }
}

