// binary-search | search / binary-search | single / p4
// Explicit naming and direct control flow.

using System;

namespace Samples;

public static class Demo
{
    public static int BinarySearch_explicit(int[] values, int target)
    {
        if (values is null) throw new ArgumentNullException(nameof(values));
        var low = 0;
        var high = values.Length - 1;
        while (low <= high)
        {
            var middle = low + (high - low) / 2;
            if (values[middle] == target) return middle;
            if (values[middle] < target) low = middle + 1;
            else high = middle - 1;
        }
        return -1;
    }

    public static void Main()
    {
        var values = new[] { 25 };
        Array.Sort(values);
        Console.WriteLine("index=" + BinarySearch_explicit(values, 25));
        Console.WriteLine(string.Join(",", values));
    }
}

