            new Sale(4, "west", 24),
            new Sale(5, "north", 12),
            new Sale(6, "south", 9),
        };

        foreach (var (region, total) in GroupByRegion_doc(sales))
        {
            Console.WriteLine(region + "=" + total);
        }
    }
}

