public static class Demo
{
    public enum Level
    {
        Low = 0,
        Medium = 1,
        High = 2,
        Critical = 3
    }

    public static Level Classify_doc(int score)
    {
        if (score < 0 || score > 100) throw new ArgumentOutOfRangeException(nameof(score));
        return score switch
        {
            < 40 => Level.Low,
            < 70 => Level.Medium,
            < 90 => Level.High,
            _ => Level.Critical
        };
    }

    public static void Main()
    {
        var score = 7;
        var level = Classify_doc(score);
        Console.WriteLine("score=" + score + " level=" + level);
        foreach (var candidate in Enum.GetValues<Level>())
        {
            Console.WriteLine(candidate + "=" + (int)candidate);
        }
    }
}

